def art(slug,title,desc,body,faqs,img="cover-1-dashboard.png"):
    cta=f'<div class="note"><b>Next steps:</b> grab <a href="{LITE}">TapeLog Lite (free)</a> · get the <a href="{FULL}">full kit ($24 one-time)</a> with DAS Trader Pro &amp; Robinhood import · <a href="{SUBL}">subscribe to the free weekly newsletter</a> · browse the <a href="/tapelog/directory/">trading tools directory</a> and <a href="/tapelog/tools/">free calculators</a>.</div>'
    page(f"/guides/{slug}/",title,desc,body+cta+"<h2>FAQ</h2>"+faq_html(faqs)+'<p class="small">Educational content, not financial advice. Updated '+TODAY+'.</p>',[faq_ld(faqs),{"@context":"https://schema.org","@type":"Article","headline":title,"description":desc,"datePublished":TODAY,"dateModified":TODAY,"author":{"@type":"Organization","name":"TapeLog"},"publisher":{"@type":"Organization","name":"TapeLog","logo":{"@type":"ImageObject","url":BASE+"/images/logo-512.png"}},"image":BASE+"/images/"+img,"mainEntityOfPage":BASE+f"/guides/{slug}/"}],img)
    ARTS.append((slug,title))
ARTS=[]
art("free-trading-journal-template-google-sheets","Free Trading Journal Template for Google Sheets (2026, No Sign-Up)","How to set up a free trading journal in Google Sheets: columns to track, the formulas for win rate, profit factor and expectancy, and a free ready-made template.",
"""<h1>Free trading journal template for Google Sheets</h1><p>Google Sheets is a good free home for a trading journal: it's in your browser, syncs across devices and has no monthly fee. Here's how to build one, or skip ahead and copy a ready-made template.</p>
<h2>Columns to track</h2><table><tr><th>Column</th><th>Example</th><th>Why</th></tr><tr><td>Date</td><td>2026-10-16</td><td>Find weekday/time patterns</td></tr><tr><td>Symbol</td><td>ABCD</td><td>P&amp;L by ticker</td></tr><tr><td>Side</td><td>Long / Short</td><td>Do you do better long or short?</td></tr><tr><td>Shares, entry, exit, fees</td><td>1000, 4.10, 4.32, 0.60</td><td>Net P&amp;L</td></tr><tr><td>Stop</td><td>3.95</td><td>Risk and R-multiple</td></tr><tr><td>Setup</td><td>ORB, VWAP reclaim</td><td>Which setups pay</td></tr><tr><td>Mistake tag / notes</td><td>Chased, early exit</td><td>Fix behavior</td></tr></table>
<h2>Formulas (paste into Google Sheets)</h2><p>Assume net P&amp;L in column J (rows 2–500).</p><pre>Net P&amp;L per trade:  =IF(C2="Long",(F2-E2)*D2,(E2-F2)*D2)-G2
Win rate:           =COUNTIF(J2:J500,"&gt;0")/COUNT(J2:J500)
Profit factor:      =SUMIF(J2:J500,"&gt;0")/ABS(SUMIF(J2:J500,"&lt;0"))
Average win:        =AVERAGEIF(J2:J500,"&gt;0")
Average loss:       =AVERAGEIF(J2:J500,"&lt;0")
Expectancy:         =AVERAGE(J2:J500)
R-multiple:         =J2/(ABS(E2-H2)*D2)</pre>
<h2>Free ready-made template</h2><p><a href="/tapelog/free-trading-journal-template/">TapeLog Lite</a> is a free .xlsx that opens in Google Sheets (File → Import, or upload to Drive and open with Sheets). It has these formulas built in for 500 trades, with no macros and no sign-up on the <a href="https://tapelog-journal.github.io/tapelog-free-trading-journal/">GitHub download page</a>.</p>""",
[("Is there a free trading journal template for Google Sheets?","Yes. TapeLog Lite is a free .xlsx template that opens in Google Sheets and calculates net P&L, win rate, profit factor and expectancy."),("How do I open an .xlsx in Google Sheets?","Upload it to Google Drive, then open it with Google Sheets, or use File, Import inside a blank sheet."),("Do Google Sheets journals need scripts?","No. All the core stats can be done with standard formulas like COUNTIF, SUMIF and AVERAGEIF.")],"cover-3-lite-free.png")
art("how-to-export-trades-from-das-trader","How to Export Trades from DAS Trader Pro to CSV (Step by Step)","How to export your fills from DAS Trader Pro's Trades window to CSV, what columns you get, and how to turn them into round-trip trades and stats.",
"""<h1>How to export trades from DAS Trader Pro</h1><p>DAS Trader Pro has no built-in journal, but its Trades window can be exported to CSV.</p>
<h2>Steps</h2><ol><li>Open the <b>Trades</b> window in DAS Trader Pro (it lists today's executions).</li><li>Right-click inside the window and choose the export option to save the trades as a CSV file.</li><li>Save it with the date in the filename (e.g. <code>das-2026-10-16.csv</code>). The window holds one day and the file has no date column.</li><li>Repeat at the end of each trading day.</li></ol>
<h2>What's in the file</h2><p>Typical columns: <code>Time, Symb, Side, Price, Qty</code>, plus fee columns such as <code>EcnFees</code>. Side codes are <b>B</b> (buy), <b>S</b> (sell), <b>SS</b> (short sell) and <b>BC</b> (buy to cover). Exact columns can vary by broker and DAS configuration.</p>
<h2>Turning fills into trades</h2><p>Each row is a fill, not a trade. Group fills by symbol and running position: a trade starts when the position leaves zero and ends when it returns to zero. The <a href="/tapelog/guides/how-to-calculate-win-rate-profit-factor-from-das-trader/">full spreadsheet method is here</a>, or paste the CSV into <a href="/tapelog/das-trader-trading-journal/">TapeLog's DAS import</a> and it does the grouping for you.</p>
<p>Can't find older days? Your broker's own statements or trade-confirmation reports are the official record; ask them for a CSV of executions.</p>""",
[("Can DAS Trader Pro export trades?","Yes. Right-click the Trades window and export to CSV. It contains that day's executions."),("Why is there no date in the DAS export?","The Trades window holds the current day only, so add the date yourself when you save or import the file."),("What do SS and BC mean in DAS?","SS is a short sell and BC is a buy to cover a short.")],"cover-2-import-to-stats.png")
art("robinhood-trade-history-export-csv","How to Export Robinhood Trade History to CSV (2026)","How to download your Robinhood trade history as a CSV using the Account activity report, what's in it, and how to analyze it in Excel or Google Sheets.",
"""<h1>How to export your Robinhood trade history to CSV</h1><p>Robinhood lets you download an <b>account activity report</b> as a CSV with your buys, sells and other activity.</p>
<h2>Steps</h2><ol><li>Open Robinhood (web or app) and go to <b>Account → Reports and statements</b>.</li><li>Choose <b>Account activity report</b> (Reports).</li><li>Select the date range and generate the report. Robinhood prepares it and makes a CSV available to download.</li><li>Download the CSV and open it in Excel or Google Sheets.</li></ol><p class="small">Menu names can change between app versions; Robinhood's help center has the current path.</p>
<h2>What's in the file</h2><p>Rows include trade dates, instrument/symbol, transaction codes (such as Buy and Sell), quantity, price and amount, alongside non-trade rows like dividends and transfers. For a trading journal, filter to stock and ETF Buy/Sell rows.</p>
<h2>Analyze it</h2><p>Pair buys and sells per symbol into round trips, then compute win rate and profit factor. Or paste the CSV into the <a href="/tapelog/robinhood-trading-journal-spreadsheet/">TapeLog Robinhood import</a>, which skips dividends, transfers, options and crypto rows automatically and adds a <a href="/tapelog/tools/pdt-day-trade-calculator/">PDT counter</a>.</p>""",
[("Can I export my Robinhood trades to Excel?","Yes. Download the Account activity report CSV from Reports and statements and open it in Excel or Google Sheets."),("Does the report include options and crypto?","It can include other activity; filter by transaction code and instrument to keep only the stock trades you want."),("How long does the report take?","Robinhood generates it in the background; it is usually available shortly after you request it.")],"cover-2-import-to-stats.png")
